export default function (pi: any) {
  pi.on("turn_end", (event: any) => {
    const text = (event.message?.content ?? []).map((c: any) => (c.type === "text" ? c.text : "")).join("");
    if (text === "Final report.") pi.sendUserMessage("Continue the requested work.", { deliverAs: "steer" });
  });
}
